const itens = $input.all();

if (!itens.length) {
  throw new Error('Nenhum alojamento recebido do Notion.');
}

return itens.map((item, index) => {
  const p = item.json;

  const pageId = p.id;
  const nome = p.properties?.Name?.title
    ?.map(t => t.plain_text ?? '')
    .join('').trim() || 'Sem nome';

  const urlAlojamento = p.properties?.URL?.url;

  if (!pageId || !urlAlojamento) {
    throw new Error(`Alojamento ${index + 1} sem ID ou URL.`);
  }

  return {
    json: {
      pageId,
      nome,
      urlAlojamento
    },
    pairedItem: { item: index }
  };
});

'use strict';

// ==================================================
// AVANTIO FOTOS — GROQ REAL
// Processar respostas acumuladas do Loop
// Compatível com Preparar JSON Avantio Lote1
// ==================================================

// 1. RECEBER RESPOSTAS E FOTOGRAFIAS

const entrada = $input.all();
const originais = $('seleciona com melhor quantidade').all();;
const idiomas = ['pt', 'es', 'en', 'fr'];

// Aceitar respostas em itens separados ou
// num único array explícito.
const resultados = entrada.flatMap(item => {
  const d = item.json;

  if (Array.isArray(d)) return d;
  if (Array.isArray(d?.data)) return d.data;
  if (Array.isArray(d?.respostas)) return d.respostas;

  return [d];
});

// 2. VERIFICAR QUANTIDADES

if (originais.length === 0) {
  throw new Error(
    'BLOQUEADO: Code_4 não contém fotografias.'
  );
}

if (resultados.length !== originais.length) {
  throw new Error(
    `BLOQUEADO: ${resultados.length} respostas Groq ` +
    `para ${originais.length} fotografias.`
  );
}

// 3. VALIDAR REFERÊNCIAS ORIGINAIS

const numeros = originais.map(item =>
  Number(item.json.pid ?? item.json.PID)
);

if (
  numeros.some(n => !Number.isInteger(n)) ||
  new Set(numeros).size !== originais.length
) {
  throw new Error(
    'BLOQUEADO: números de fotografia inválidos ou repetidos.'
  );
}

const totais = originais.map(item =>
  Number(item.json.qtdFotos)
);

if (
  totais.some(n => n !== originais.length)
) {
  throw new Error(
    'BLOQUEADO: total de fotografias inconsistente no Code_4.'
  );
}

// 4. FUNÇÕES AUXILIARES

function textoValido(valor) {
  return typeof valor === 'string' &&
    valor.trim().length > 0;
}

function extrairConteudo(resposta) {
  return (
    resposta?.choices?.[0]?.message?.content ??
    resposta?.content?.parts?.[0]?.text ??
    resposta?.text ??
    resposta?.output ??
    null
  );
}

function limparJSON(texto) {
  return texto
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

// 5. PROCESSAR CADA RESPOSTA

return resultados.map((resposta, index) => {

  const original = originais[index].json;

  const numero = Number(
    original.pid ?? original.PID
  );

  const base = {
    alojamento: {
      pageId: original.pageId ?? '',
      nome: original.nome ?? '',
      urlAnuncio: original.urlAlojamento ?? ''
    },

    foto: {
      numero,
      url: original.fotoUrl ?? '',
      total: original.qtdFotos ?? null
    }
  };

  function falhar(mensagem) {
    return {
      json: {
        ...base,
        sucesso: false,
        erro: mensagem
      }
    };
  }

  // Verificar identidade da fotografia

  if (
    !textoValido(base.alojamento.pageId) ||
    !textoValido(base.alojamento.nome) ||
    !textoValido(base.alojamento.urlAnuncio) ||
    !textoValido(base.foto.url)
  ) {
    return falhar(
      `Fotografia ${numero}: identificação incompleta.`
    );
  }

  // Verificar resposta da Groq

  const conteudo = extrairConteudo(resposta);

  if (!textoValido(conteudo)) {
    const erro = resposta?.error?.message ??
      resposta?.error ??
      'Sem conteúdo válido';

    return falhar(
      `Fotografia ${numero}: ${String(erro)}`
    );
  }

  // Converter resposta em JSON

  let dados;

  try {
    dados = JSON.parse(limparJSON(conteudo));
  } catch (erro) {
    return falhar(
      `Fotografia ${numero}: JSON inválido — ` +
      erro.message
    );
  }

  if (
    !dados ||
    typeof dados !== 'object' ||
    !textoValido(dados.etiqueta) ||
    !dados.traducoes ||
    typeof dados.traducoes !== 'object'
  ) {
    return falhar(
      `Fotografia ${numero}: etiqueta ou traduções ausentes.`
    );
  }

  // 6. NORMALIZAR TRADUÇÕES

  const traducoes = {};

  for (const idioma of idiomas) {

    const t = dados.traducoes[idioma] ?? {};

    traducoes[idioma] = {
      title: t.title ?? t.titulo ?? '',
      descricao:
        t.descricao ??
        t.description ??
        t.descripcion ??
        '',
      alt: t.alt ?? ''
    };
  }

  // 7. VALIDAR CAMPOS OBRIGATÓRIOS

  const completos = idiomas.every(idioma => {
    const t = traducoes[idioma];

    return (
      textoValido(t.title) &&
      textoValido(t.descricao) &&
      textoValido(t.alt) &&
      t.title.length <= 70 &&
      t.alt.length <= 125
    );
  });

  if (!completos) {
    return {
      json: {
        ...base,
        nome: traducoes.pt.title ?? '',
        etiqueta: dados.etiqueta,
        acessibilidade: false,
        traducoes,
        sucesso: false,
        erro:
          `Fotografia ${numero}: campos em falta ` +
          'ou limites de caracteres excedidos.'
      }
    };
  }

  // 8. RESULTADO FINAL DA FOTOGRAFIA

  return {
    json: {
      ...base,
      nome: traducoes.pt.title,
      etiqueta: dados.etiqueta,
      acessibilidade: false,
      traducoes,
      sucesso: true
    }
  };

});

'use strict';

// ==================================================
// AVANTIO FOTOS — PREPARAR JSON FINAL
// Compatível com Groq real e Mock Data
// Saída: VALIDADO ou BLOQUEADO
// Não modifica dados no Avantio
// ==================================================

// ==================================================
// 1. REUNIR OS REGISTOS
// ==================================================

const items = $input.all();
const idiomas = ['pt', 'es', 'en', 'fr'];

const registos = items.flatMap(item => {
  const dados = item.json;

  if (Array.isArray(dados)) return dados;

  if (dados && Array.isArray(dados.fotos)) {
    return dados.fotos;
  }

  if (dados && Array.isArray(dados.data)) {
    return dados.data;
  }

  return dados ? [dados] : [];
});

if (registos.length === 0) {
  throw new Error(
    'BLOQUEADO: não foram recebidas fotografias.'
  );
}

// ==================================================
// 2. RECUPERAR IDENTIFICAÇÃO DE CADA REGISTO
// ==================================================

function identificar(registo) {
  const a = registo.alojamento;
  const f = registo.foto ?? registo;

  return {
    pageId:
      (typeof a === 'object' && a !== null
        ? a.pageId : null) ??
      registo.pageId ??
      null,

    nome:
      (typeof a === 'string'
        ? a
        : a?.nome) ??
      registo.alojamentoNome ??
      null,

    url:
      (typeof a === 'object' && a !== null
        ? a.urlAnuncio ?? a.urlAlojamento
        : null) ??
      registo.urlAnuncio ??
      registo.urlAlojamento ??
      null,

    total:
      f.total ??
      registo.qtdFotos ??
      registo.totalFotos ??
      null
  };
}

const identificacoes = registos.map(identificar);

// ==================================================
// 3. VALIDAR QUE É APENAS UM ALOJAMENTO
// ==================================================

const ids = [
  ...new Set(identificacoes.map(a => a.pageId))
];

const nomesAlojamento = [
  ...new Set(identificacoes.map(a => a.nome))
];

const urlsAnuncio = [
  ...new Set(identificacoes.map(a => a.url))
];

if (
  ids.length !== 1 ||
  typeof ids[0] !== 'string' ||
  !ids[0].trim() ||
  nomesAlojamento.length !== 1 ||
  typeof nomesAlojamento[0] !== 'string' ||
  !nomesAlojamento[0].trim() ||
  urlsAnuncio.length !== 1 ||
  typeof urlsAnuncio[0] !== 'string' ||
  !urlsAnuncio[0].trim()
) {
  throw new Error(
    'BLOQUEADO: as fotografias não pertencem ' +
    'inequivocamente ao mesmo alojamento.'
  );
}

const pageId = ids[0];
const alojamentoNome = nomesAlojamento[0];
const urlAnuncio = urlsAnuncio[0];

// ==================================================
// 4. VALIDAR QUANTIDADE TOTAL
// ==================================================

const totais = [
  ...new Set(
    identificacoes.map(a => Number(a.total))
  )
];

if (
  totais.length !== 1 ||
  !Number.isInteger(totais[0]) ||
  totais[0] < 1
) {
  throw new Error(
    'BLOQUEADO: quantidade total de fotografias ' +
    'ausente ou inconsistente.'
  );
}

const totalEsperado = totais[0];

if (registos.length !== totalEsperado) {
  throw new Error(
    `BLOQUEADO: eram esperadas ${totalEsperado} ` +
    `fotografias, mas chegaram ${registos.length}.`
  );
}

// ==================================================
// 5. ORDENAR AS FOTOGRAFIAS
// ==================================================

registos.sort((a, b) => {
  const numeroA = Number(
    a.foto?.numero ?? a.numero ?? 0
  );

  const numeroB = Number(
    b.foto?.numero ?? b.numero ?? 0
  );

  return numeroA - numeroB;
});

// ==================================================
// 6. MAPA DE ETIQUETAS DO AVANTIO
// ==================================================

const etiquetas = {
  'balcão': 14,
  'counter': 14,
  'mostrador': 14,
  'comptoir': 14,

  'cafeteria': 16,
  'cafetería': 16,

  "child's bedroom": 20,
  'quarto infantil': 20,
  'dormitorio infantil': 20,
  "chambre d'enfant": 20,

  'cozinha': 1,
  'kitchen': 1,
  'cocina': 1,
  'cuisine': 1,

  'detalhes': 10,
  'details': 10,
  'detalles': 10,
  'détails': 10,

  'exterior': 9,

  'fachada': 2,
  'facade': 2,
  'façade': 2,

  'garagem': 8,
  'garage': 8,

  'jardim': 5,
  'garden': 5,
  'jardín': 5,

  'outros': 11,
  'other': 11,
  'otros': 11,
  'autres': 11,

  'piscina': 6,
  'pool': 6,
  'swimming pool': 6,
  'piscine': 6,

  'plano': 18,
  'floor plan': 18,
  'plano de planta': 18,
  'plan': 18,

  'quarto de banho': 4,
  'bathroom': 4,
  'baño': 4,
  'salle de bain': 4,

  'quarto': 3,
  'quarto de cama': 3,
  'dormitorio': 3,
  'bedroom': 3,
  'chambre': 3,

  'receção': 13,
  'recepcion': 13,
  'recepción': 13,
  'reception': 13,
  'réception': 13,

  'resort': 19,

  'sala de estar': 12,
  'living room': 12,
  'salon': 12,
  'séjour': 12,

  'sala de jantar': 15,
  'dining room': 15,
  'comedor': 15,
  'salle à manger': 15,

  'terraço': 7,
  'terrace': 7,
  'terraza': 7,
  'terrasse': 7,

  'visualizações': 17,
  'views': 17,
  'vistas': 17,
  'vue': 17,
  'vues': 17
};

const idsValidos = new Set(
  Object.values(etiquetas)
);

// ==================================================
// 7. NORMALIZAR E IDENTIFICAR ETIQUETAS
// ==================================================

function normalizarEtiqueta(valor) {
  if (typeof valor !== 'string') return null;

  return valor
    .trim()
    .toLocaleLowerCase()
    .normalize('NFC');
}

function obterEtiqueta(original) {

  const nomes = typeof original === 'string'
    ? [original]
    : [
        original?.pt,
        original?.nome,
        original?.es,
        original?.en,
        original?.fr
      ];

  // Se receber um ID, validar a categoria.
  if (
    original &&
    typeof original === 'object' &&
    original.id !== undefined &&
    original.id !== null &&
    original.id !== ''
  ) {
    const id = Number(original.id);

    if (Number.isInteger(id) && idsValidos.has(id)) {

      const nomeOriginal = nomes.find(
        n => typeof n === 'string' && n.trim()
      );

      // Não aceitar um ID contraditório com o nome.
      if (nomeOriginal) {
        const chave = normalizarEtiqueta(nomeOriginal);
        const idDoNome = etiquetas[chave];

        if (
          idDoNome !== undefined &&
          idDoNome !== id
        ) {
          return {
            nome: nomeOriginal,
            id: null
          };
        }
      }

      return {
        nome: nomeOriginal ?? null,
        id
      };
    }

    // Não substituir silenciosamente um ID inválido.
    return {
      nome: nomes.find(
        n => typeof n === 'string' && n.trim()
      ) ?? null,
      id: null
    };
  }

  // Caso a Groq devolva a etiqueta como texto.
  for (const nome of nomes) {
    const chave = normalizarEtiqueta(nome);

    if (
      chave &&
      etiquetas[chave] !== undefined
    ) {
      return {
        nome: nome.trim(),
        id: etiquetas[chave]
      };
    }
  }

  return {
    nome: nomes.find(
      n => typeof n === 'string' && n.trim()
    ) ?? null,
    id: null
  };
}

// ==================================================
// 8. CONSTRUIR O JSON DAS FOTOGRAFIAS
// ==================================================

const fotos = registos.map((registo) => {

  const foto = registo.foto ?? registo;

  const traducoesOriginais =
    registo.traducoes ??
    foto.traducoes ??
    {};

  const traducoes = {};

  for (const idioma of idiomas) {

    const t = traducoesOriginais[idioma] ?? {};

    traducoes[idioma] = {
      title:
        t.title ??
        t.titulo ??
        '',

      descricao:
        t.descricao ??
        t.description ??
        t.descripcion ??
        '',

      alt:
        t.alt ??
        ''
    };
  }

  const etiqueta = obterEtiqueta(
    registo.etiqueta ?? foto.etiqueta
  );

  return {
    numero: Number(
      foto.numero ?? registo.numero
    ),

    url:
      foto.url ??
      foto.fotoUrl ??
      registo.url ??
      registo.fotoUrl ??
      null,

    nome:
      registo.nome ??
      foto.nome ??
      traducoes.pt.title ??
      null,

    etiqueta,

    acessibilidade:
      registo.acessibilidade ??
      foto.acessibilidade ??
      false,

    traducoes,

    sucesso:
      registo.sucesso ??
      foto.sucesso ??
      false
  };
});

// ==================================================
// 9. VALIDAR TODOS OS CAMPOS
// ==================================================

const diagnostico = [];

for (const foto of fotos) {

  const problemas = [];

  // Verificar sucesso da IA.
  if (foto.sucesso !== true) {
    problemas.push(
      'A análise da IA não foi concluída com sucesso'
    );
  }

  // Número da fotografia.
  if (
    !Number.isInteger(foto.numero) ||
    foto.numero < 1 ||
    foto.numero > totalEsperado
  ) {
    problemas.push('Número da fotografia inválido');
  }

  // URL da fotografia.
  if (
    typeof foto.url !== 'string' ||
    !foto.url.trim() ||
    !/^https:\/\//i.test(foto.url)
  ) {
    problemas.push('URL da fotografia inválida');
  }

  // Nome principal.
  if (
    typeof foto.nome !== 'string' ||
    !foto.nome.trim()
  ) {
    problemas.push('Nome principal em falta');
  }

  // Etiqueta.
  if (
    typeof foto.etiqueta.nome !== 'string' ||
    !foto.etiqueta.nome.trim()
  ) {
    problemas.push('Nome da etiqueta em falta');
  }

  if (
    !Number.isInteger(foto.etiqueta.id) ||
    !idsValidos.has(foto.etiqueta.id)
  ) {
    problemas.push(
      `Etiqueta Avantio inválida: ${foto.etiqueta.nome}`
    );
  }

  // Acessibilidade permanece desativada.
  if (foto.acessibilidade !== false) {
    problemas.push(
      'Acessibilidade deve permanecer desativada'
    );
  }

  // Validar as quatro traduções.
  for (const idioma of idiomas) {

    const t = foto.traducoes[idioma];

    // Título.
    if (
      typeof t.title !== 'string' ||
      !t.title.trim()
    ) {
      problemas.push(`Título ${idioma} vazio`);
    } else if (t.title.length > 70) {
      problemas.push(
        `Título ${idioma} excede 70 caracteres ` +
        `(${t.title.length})`
      );
    }

    // Descrição.
    if (
      typeof t.descricao !== 'string' ||
      !t.descricao.trim()
    ) {
      problemas.push(`Descrição ${idioma} vazia`);
    }

    // Texto alternativo.
    if (
      typeof t.alt !== 'string' ||
      !t.alt.trim()
    ) {
      problemas.push(`Alt ${idioma} vazio`);
    } else if (t.alt.length > 125) {
      problemas.push(
        `Alt ${idioma} excede 125 caracteres ` +
        `(${t.alt.length})`
      );
    }
  }

  // Registar problemas desta fotografia.
  if (problemas.length > 0) {
    diagnostico.push({
      numero: foto.numero,
      problemas
    });
  }
}

// ==================================================
// 10. DETETAR NÚMEROS REPETIDOS
// ==================================================

const numeros = fotos.map(f => f.numero);

const numerosRepetidos = numeros.filter(
  (numero, indice) =>
    numeros.indexOf(numero) !== indice
);

if (numerosRepetidos.length > 0) {
  diagnostico.push({
    numero: null,
    problemas: [
      'Existem números de fotografia repetidos: ' +
      [...new Set(numerosRepetidos)].join(', ')
    ]
  });
}

// ==================================================
// 11. DETETAR NÚMEROS EM FALTA
// ==================================================

const esperados = Array.from(
  { length: totalEsperado },
  (_, i) => i + 1
);

const numerosEmFalta = esperados.filter(
  numero => !numeros.includes(numero)
);

if (numerosEmFalta.length > 0) {
  diagnostico.push({
    numero: null,
    problemas: [
      'Faltam fotografias com os números: ' +
      numerosEmFalta.join(', ')
    ]
  });
}

// ==================================================
// 12. DETETAR URLS REPETIDAS
// ==================================================

const urlsFotos = fotos.map(f => f.url);

const urlsRepetidas = urlsFotos.filter(
  (url, indice) =>
    typeof url === 'string' &&
    urlsFotos.indexOf(url) !== indice
);

if (urlsRepetidas.length > 0) {
  diagnostico.push({
    numero: null,
    problemas: [
      'Existem URLs de fotografias repetidas no lote.'
    ]
  });
}

// ==================================================
// 13. DEVOLVER DIAGNÓSTICO SE HOUVER ERROS
// ==================================================

if (diagnostico.length > 0) {

  return [{
    json: {
      estado: 'BLOQUEADO',
      alojamento: alojamentoNome,
      pageId,
      urlAnuncio,

      fotografiasEsperadas: totalEsperado,
      fotografiasAnalisadas: fotos.length,

      fotografiasComProblemas: diagnostico.filter(
        item => item.numero !== null
      ).length,

      erros: diagnostico.map(item => ({
        fotografia: item.numero,
        problemas: item.problemas
      })),

      aviso:
        'Lote bloqueado para diagnóstico. ' +
        'Não utilizar este resultado para preencher o Avantio.'
    }
  }];
}

// ==================================================
// 14. DEVOLVER JSON FINAL VALIDADO
// ==================================================

return [{
  json: {
    estado: 'VALIDADO',
    alojamento: alojamentoNome,
    pageId,
    urlAnuncio,
    totalFotos: fotos.length,
    fotos
  }
}];

const dados = $input.first().json;

// JSON que queremos guardar
const conteudo = JSON.stringify(dados, null, 2);

// O Notion permite no máximo 2000 caracteres
// por objeto de rich_text.
const partes = conteudo.match(/[\s\S]{1,1900}/g) || [];

const richText = partes.map(parte => ({
  type: "text",
  text: {
    content: parte
  }
}));

return [{
  json: {
    pageId: dados.pageId,
    blocks: [
      {
        object: "block",
        type: "code",
        code: {
          language: "json",
          rich_text: richText
        }
      }
    ]
  }
}];

// NODE: Classificar erro GROQ
// Apenas identifica o erro e a fotografia. Não valida traduções aqui.
const entrada = $input.first().json;

const mensagem = String(
  entrada.error?.description ??
  entrada.details?.description ??
  entrada.error?.message ??
  entrada.details?.message ??
  ''
);

const httpCode = String(
  entrada.details?.httpCode ??
  entrada.error?.httpCode ??
  (mensagem.match(/\b(429|500|502|503|504)\b/)?.[1] ?? '')
);

if (!['429', '500', '502', '503', '504'].includes(httpCode)) {
  throw new Error('Erro Groq não recuperável: ' + JSON.stringify(entrada).slice(0, 1200));
}

const tipoErro = httpCode === '429' ? 'LIMITE_GROQ' :
  httpCode === '503' ? 'GROQ_INDISPONIVEL' : 'ERRO_TEMPORARIO_GROQ';

const originais = $('seleciona com melhor quantidade').all().map(item => item.json);
if (!originais.length) throw new Error('Lista original de fotografias vazia.');

const indiceFalha = originais.findIndex(f =>
  f.pageId === entrada.pageId &&
  Number(f.pid) === Number(entrada.pid) &&
  f.fotoUrl === entrada.fotoUrl
);
if (indiceFalha < 0) {
  throw new Error('Fotografia do erro não encontrada na lista original.');
}

const primeira = originais[0];
if (
  originais.some((f, i) =>
    f.pageId !== primeira.pageId ||
    f.nome !== primeira.nome ||
    f.urlAlojamento !== primeira.urlAlojamento ||
    Number(f.pid) !== i + 1 ||
    Number(f.qtdFotos) !== originais.length ||
    typeof f.fotoUrl !== 'string' || !f.fotoUrl.startsWith('https://')
  ) ||
  new Set(originais.map(f => f.fotoUrl)).size !== originais.length
) {
  throw new Error('Lista original inconsistente. Não guardar no Notion.');
}

return [{ json: {
  indiceFalha,
  fotoFalhou: Number(originais[indiceFalha].pid),
  urlFalhou: originais[indiceFalha].fotoUrl,
  pageId: primeira.pageId,
  alojamento: primeira.nome,
  urlAnuncio: primeira.urlAlojamento,
  totalFotos: originais.length,
  tipoErro,
  httpCode,
  mensagem
}}];

// Recupera apenas as respostas de SUCESSO anteriores à chamada que atingiu o limite.
// Se não for possível associar resposta/fotografia, falha sem escrever no Notion.
const info = $input.first().json;

const tiposPermitidos = [
  'LIMITE_GROQ',
  'GROQ_INDISPONIVEL',
  'ERRO_TEMPORARIO_GROQ'
];


if (!tiposPermitidos.includes(info.tipoErro)) {
  throw new Error(
    'Erro não recuperável: ' + info.tipoErro
  );
}



const originais = $('seleciona com melhor quantidade').all().map(item => item.json);
const indiceFalha = Number(info.indiceFalha);
const totalFotos = originais.length;
if (!totalFotos || !Number.isInteger(indiceFalha) ||
    indiceFalha < 0 || indiceFalha >= totalFotos) {
  throw new Error('Índice ou quantidade de fotos inválidos para recuperação.');
}

const primeira = originais[0];
const pageId = primeira.pageId;
const alojamento = primeira.nome;
const urlAnuncio = primeira.urlAlojamento;
if (!pageId || !alojamento || !urlAnuncio ||
    originais.some((f, i) =>
      f.pageId !== pageId || f.urlAlojamento !== urlAnuncio ||
      f.nome !== alojamento || f.pid !== i + 1 ||
      f.qtdFotos !== totalFotos ||
      typeof f.fotoUrl !== 'string' || !f.fotoUrl.startsWith('https://')
    ) || new Set(originais.map(f => f.fotoUrl)).size !== totalFotos) {
  throw new Error('Fotografias/identificação inconsistentes; Notion não será alterado.');
}
if (originais[indiceFalha].fotoUrl !== info.urlFalhou ||
    originais[indiceFalha].pid !== info.fotoFalhou) {
  throw new Error('A fotografia do erro não corresponde ao item do loop.');
}

const etiquetas = {
  'Balcão':14, 'Cafeteria':16, "Child's bedroom":20,
  'Cozinha':1, 'Detalhes':10, 'Exterior':9, 'Fachada':2,
  'Garagem':8, 'Jardim':5, 'Outros':11, 'Piscina':6,
  'Plano':18, 'Quarto de banho':4, 'Quarto':3,
  'Receção':13, 'Resort':19, 'Sala de estar':12,
  'Sala de jantar':15, 'Terraço':7, 'Visualizações':17
};
const textoOk = s => typeof s === 'string' && !!s.trim();
const fotos = [];

for (let i = 0; i < indiceFalha; i++) {
  let itensDaChamada;
  try {
    // 0: saída de sucesso; i: índice da chamada Groq dentro do loop.
    itensDaChamada = $('GROQ - Descrições, ALT, Títulos').all(0, i);
  } catch (e) {
    throw new Error(`Não foi possível recuperar a resposta Groq da foto ${i + 1}: ${e.message}`);
  }
  if (!Array.isArray(itensDaChamada) || itensDaChamada.length !== 1) {
    throw new Error(`Foto ${i + 1}: esperava exatamente uma resposta Groq.`);
  }
  const resposta = itensDaChamada[0].json;
  if (resposta.error) {
    throw new Error(`Foto ${i + 1}: não existe uma resposta bem-sucedida.`);
  }
  const texto = resposta.choices?.[0]?.message?.content;
  if (!textoOk(texto)) {
    throw new Error(`Foto ${i + 1}: resposta Groq sem JSON de conteúdo.`);
  }
  let dados;
  try {
    dados = JSON.parse(texto.replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/i, '').trim());
  } catch (e) {
    throw new Error(`Foto ${i + 1}: JSON Groq inválido: ${e.message}`);
  }
  if (!textoOk(dados?.etiqueta) || !etiquetas[dados.etiqueta]) {
    throw new Error(`Foto ${i + 1}: etiqueta inexistente ou inválida.`);
  }
  const traducoes = {};
  for (const idioma of ['pt', 'es', 'en', 'fr']) {
    const t = dados.traducoes?.[idioma] ?? {};
    const title = t.title ?? t.titulo ?? '';
    const descricao = t.descricao ?? t.description ?? t.descripcion ?? '';
    const alt = t.alt ?? '';
    if (!textoOk(title) || title.length > 70 ||
        !textoOk(descricao) || !textoOk(alt) || alt.length > 125) {
      throw new Error(`Foto ${i + 1}: campos de ${idioma} incompletos ou inválidos.`);
    }
    traducoes[idioma] = {title, descricao, alt};
  }
  fotos.push({
    numero:i+1,
    url:originais[i].fotoUrl,
    nome:traducoes.pt.title,
    etiqueta:{nome:dados.etiqueta, id:etiquetas[dados.etiqueta]},
    acessibilidade:false,
    traducoes,
    sucesso:true
  });
}

const pendentes = originais.slice(indiceFalha).map(f => ({
  numero:f.pid,
  url:f.fotoUrl
}));
if (fotos.length + pendentes.length !== totalFotos || !pendentes.length) {
  throw new Error('Contagem do lote parcial inconsistente.');
}
return [{ json: {
  estado: fotos.length ? 'PARCIAL' : 'PENDENTE',
  alojamento,
  pageId,
  urlAnuncio,
  totalFotos,
  fotos,
  fotosProcessadas:fotos.length,
  pendentes,
  proximaFoto:pendentes[0].numero
}}];

const dados = $input.first().json;
if (!['PARCIAL', 'PENDENTE'].includes(dados.estado)) {
