}
if (!dados.pageId || !Array.isArray(dados.fotos) ||
    !Number.isInteger(dados.totalFotos) || dados.totalFotos < 1) {
  throw new Error('Dados incompletos para publicação no Notion.');
}
if (dados.estado === 'VALIDADO') {
  if (dados.fotos.length !== dados.totalFotos ||
      dados.fotos.some(f => f.sucesso !== true)) {
    throw new Error('VALIDADO sem todas as fotos completas.');
  }
} else {
  if (!Array.isArray(dados.pendentes) || !dados.pendentes.length ||
      dados.fotos.length + dados.pendentes.length !== dados.totalFotos ||
      dados.proximaFoto !== dados.pendentes[0].numero) {
    throw new Error('PARCIAL/PENDENTE sem contagem ou URLs consistentes.');
  }
  const numeros = [...dados.fotos.map(f=>f.numero), ...dados.pendentes.map(f=>f.numero)];
  if (new Set(numeros).size !== dados.totalFotos ||
      numeros.some(n=>!Number.isInteger(n) || n<1 || n>dados.totalFotos) ||
      dados.pendentes.some(f=>typeof f.url!=='string' || !f.url.startsWith('https://'))) {
    throw new Error('PARCIAL/PENDENTE com números ou URLs inválidos.');
  }
}
const statusNotion = 'PS';
const conteudo = JSON.stringify(dados, null, 2);
const partes = conteudo.match(/[\s\S]{1,1900}/g) || [];
if (partes.length > 100) {
  throw new Error('JSON demasiado grande para um único bloco Notion.');
}
return [{json:{
  pageId:dados.pageId,
  statusNotion,
  blocks:[{
    object:'block', type:'code',
    code:{language:'json',rich_text:partes.map(parte=>({
      type:'text',text:{content:parte}
    }))}
  }]
}}];

const respostas = $input.all();
const alojamentos = $('Code_1').all();

if (respostas.length !== alojamentos.length) {
  throw new Error(
    `Recebidos ${respostas.length} HTMLs para ${alojamentos.length} alojamentos.`
  );
}

return respostas.map((item, i) => {
  const dados = alojamentos[i].json;

  const html = String(
    item.json.data ?? item.json.body ?? ''
  )
    .replace(/\\\//g, '/')
    .replace(/&amp;/gi, '&');

  // Extrair fotografias independentemente do idioma:
  // /aluguer/fotos/
  // /en/rentals/fotos/
  // /de/vermietung/fotos/
  // Também suporta outras versões linguísticas.
  const regex = /https:\/\/www\.mtphomes\.pt\/(?:[^/"'<>\s\\]+\/){1,2}fotos\/3\/[^/"'<>\s\\]+\/big[^/"'<>\s\\?]+\.(?:jpg|jpeg|png|webp)/gi;

  // Remover URLs duplicadas
  const fotos = [...new Set(html.match(regex) || [])];

  // Se não encontrou fotografias, registar diagnóstico
  // sem interromper os restantes alojamentos
  if (!fotos.length) {
    return {
      json: {
        pageId: dados.pageId,
        nome: dados.nome,
        urlAlojamento: dados.urlAlojamento,
        qtdFotos: null,
        fotos: [],
        erroExtracao: 'SEM_FOTOGRAFIAS_EXTRAIDAS',
        tamanhoHTML: html.length,
        tituloPagina: html.match(
          /<title[^>]*>([\s\S]*?)<\/title>/i
        )?.[1]?.trim() ?? null,
        contemPastaFotos: html.includes('/fotos/')
      }
    };
  }

  return {
    json: {
      pageId: dados.pageId,
      nome: dados.nome,
      urlAlojamento: dados.urlAlojamento,
      qtdFotos: fotos.length,
      fotos
    }
  };
});

const alojamentos = $input.all().map(i => i.json);

const validos = alojamentos.filter(a =>
  a.pageId &&
  a.nome &&
  a.urlAlojamento &&
  Array.isArray(a.fotos) &&
  a.fotos.length > 0 &&
  Number(a.qtdFotos) === a.fotos.length &&
  !a.erroExtracao
);

if (!validos.length) {
  throw new Error(
    'Nenhum alojamento válido: ' +
    JSON.stringify(alojamentos.map(a => ({
      nome: a.nome,
      qtdFotos: a.qtdFotos,
      erro: a.erroExtracao
    })))
  );
}

validos.sort(
  (a, b) => a.fotos.length - b.fotos.length
);

const escolhido = validos[0];

return escolhido.fotos.map((fotoUrl, index) => ({
  json: {
    pageId: escolhido.pageId,
    nome: escolhido.nome,
    urlAlojamento: escolhido.urlAlojamento,
    qtdFotos: escolhido.fotos.length,
    pid: index + 1,
    fotoUrl
  }
}));

